describe("docking", () => {
  const harbourRows = [
    "..........",
    "..........",
    "...####...",
    "...##D....",
    "..........",
    "..........",
  ];
  const harbour = testConfig(harbourRows);
  // A dock on the corner of an island, as the slice sea's docks are: land to its west and north, open sea to its east
  // and south, with room to run up to it.
  const cornerIsland = testConfig([
    "................",
    "................",
    "................",
    "................",
    "....######......",
    "....######......",
    "....######......",
    "....#####D......",
    "................",
    "................",
    "................",
    "................",
    "................",
    "................",
  ]);
  const dock = harbour.map.docks[0]!;
  const berth = tileCentre(harbour, dock.tileX, dock.tileY);
  const nearby = { ...shipAt(5, 5, 0, harbour), y: berth.y + tile, x: berth.x + 40 };

  it("moors a slow ship near a dock with interact: it stops at the dock and records it", () => {
    const moored = sail(harbour, { ...nearby, speed: harbour.ship.dockMaxSpeed }, INTERACT);
    expect(moored).toMatchObject({ x: berth.x, y: berth.y, speed: 0, dock: dock.id });
    // It stays moored without throttle, turning or not, interact held or not.
    for (const input of [INTERACT, helm(0, 0), helm(1, 0)]) {
      expect(sailFor(moored, input, 20, harbour).at(-1)).toEqual(moored);
    }
  });

  it("docks at any speed, but not too far or without interact", () => {
    expect(sail(harbour, { ...nearby, speed: harbour.ship.maxSpeed }, INTERACT)).toMatchObject({ ...berth, speed: 0, dock: dock.id });
    expect(sail(harbour, { ...nearby, speed: -harbour.ship.maxReverseSpeed }, INTERACT)).toMatchObject({ ...berth, speed: 0, dock: dock.id });
    expect(sail(harbour, { ...nearby, y: berth.y + 2 * tile }, INTERACT).dock).toBe(NOT_DOCKED);
    expect(sail(harbour, nearby, helm(0, 0)).dock).toBe(NOT_DOCKED);
    expect(sail(harbour, nearby, FULL_AHEAD).dock).toBe(NOT_DOCKED);
  });

  it("docks with the throttle held, ahead or astern, at any speed", () => {
    expect(sail(harbour, nearby, helm(0, -1, INTERACT_BUTTON))).toMatchObject({ ...berth, speed: 0, dock: dock.id });
    expect(sail(harbour, nearby, helm(0, 1, INTERACT_BUTTON))).toMatchObject({ ...berth, speed: 0, dock: dock.id });
    expect(sail(harbour, { ...nearby, speed: harbour.ship.maxSpeed }, helm(0, 1, INTERACT_BUTTON))).toMatchObject({ ...berth, speed: 0, dock: dock.id });
  });

  it("docks a ship driven at its dock with ahead held as soon as it is within reach, still at full speed", () => {
    // Heading north (48) from three tiles south of the dock at full speed, full ahead and interact held throughout, as
    // a player drives in: it moors on the first step it starts within the dock's reach, without slowing down first.
    const approach = { ...shipAt(dock.tileX, dock.tileY + 3, 48, harbour), speed: harbour.ship.maxSpeed };
    const course = sailFor(approach, helm(0, 1, INTERACT_BUTTON), 40, harbour);
    const moored = course.findIndex((ship) => ship.dock !== NOT_DOCKED);
    expect(course[moored - 1]!.speed).toBe(harbour.ship.maxSpeed);
    expect(dockInReach(harbour, course[moored - 2]!.x, course[moored - 2]!.y)).toBeUndefined();
    expect(dockInReach(harbour, course[moored - 1]!.x, course[moored - 1]!.y)).toBe(dock);
    expect(course.at(-1)).toMatchObject({ ...berth, speed: 0, dock: dock.id });
  });

  it("moors beside the berth across a corner of land, and checks the straight run to the berth for the hull", () => {
    // South-west of the dock, diagonally: the straight run to the berth crosses the corner of the land tile west of the
    // dock, but the tile south of the dock is open, so the ship is beside the berth and moors.
    const diagonal = shipAt(dock.tileX - 1, dock.tileY + 1, 0, harbour);
    expect((berth.x - diagonal.x) ** 2 + (berth.y - diagonal.y) ** 2).toBeLessThanOrEqual(harbour.ship.dockRadius ** 2);
    expect(hullIsClear(harbour, diagonal.x, diagonal.y)).toBe(true);
    expect(terrainAt(harbour.map, dock.tileX - 1, dock.tileY)).toBe(Terrain.Land);
    expect(terrainAt(harbour.map, dock.tileX, dock.tileY + 1)).toBe(Terrain.Sea);
    expect(hullPathIsClear(harbour, diagonal.x, diagonal.y, berth.x, berth.y)).toBe(false);
    expect(sail(harbour, diagonal, INTERACT)).toMatchObject({ ...berth, speed: 0, dock: dock.id });
    // Straight up from the tile south of the dock the run is clear, and it moors.
    const below = shipAt(dock.tileX, dock.tileY + 1, 0, harbour);
    expect(hullPathIsClear(harbour, below.x, below.y, berth.x, berth.y)).toBe(true);
    expect(sail(harbour, below, INTERACT)).toMatchObject({ ...berth, dock: dock.id });
    // The check follows the whole segment, not just its ends: both ends clear, a shoal between them.
    const shoaled = testConfig(["..........", "..........", "....%.....", ".........."]);
    expect(hullIsClear(shoaled, 3 * tile + tile / 2, 2 * tile + tile / 2)).toBe(true);
    expect(hullPathIsClear(shoaled, 3 * tile + tile / 2, 2 * tile + tile / 2, 5 * tile + tile / 2, 2 * tile + tile / 2)).toBe(false);
    expect(hullPathIsClear(shoaled, 3 * tile + tile / 2, 1 * tile + tile / 2, 5 * tile + tile / 2, 1 * tile + tile / 2)).toBe(true);
  });

  it("moors beside the berth only if a diagonal neighbour is not pinched between land or shoal on both shared sides", () => {
    // South-west of the dock, with land west of it, and south of it land in one test sea and a shoal in the other.
    for (const [kind, south] of [["land", "#"], ["shoal", "%"]] as const) {
      const pinched = testConfig(["..........", "...####...", "...##D....", `.....${south}....`, ".........."]);
      const pinchedDock = pinched.map.docks[0]!;
      const pinchedBerth = tileCentre(pinched, pinchedDock.tileX, pinchedDock.tileY);
      const diagonal = shipAt(pinchedDock.tileX - 1, pinchedDock.tileY + 1, 0, pinched);
      expect(hullIsClear(pinched, diagonal.x, diagonal.y), kind).toBe(true);
      expect((pinchedBerth.x - diagonal.x) ** 2 + (pinchedBerth.y - diagonal.y) ** 2, kind).toBeLessThanOrEqual(pinched.ship.dockRadius ** 2);
      expect(dockInReach(pinched, diagonal.x, diagonal.y), kind).toBeUndefined();
      expect(sail(pinched, diagonal, INTERACT), kind).toEqual(diagonal);
      // East of the dock, the orthogonal neighbour, it moors.
      expect(sail(pinched, shipAt(pinchedDock.tileX + 1, pinchedDock.tileY, 0, pinched), INTERACT).dock, kind).toBe(pinchedDock.id);
    }
  });

  it("does not moor behind land from within a longer reach, unless beside the berth or with a clear run", () => {
    // A 640 reach (the shipped reach stays 384, which the berth's neighbours already cover).
    const far = testConfig(harbourRows, { dockRadius: 640 });
    const farDock = far.map.docks[0]!;
    const farBerth = tileCentre(far, farDock.tileX, farDock.tileY);
    // Two rows north of the dock, beyond the land north of it: within reach, not beside the berth, no clear run.
    const behind = shipAt(farDock.tileX, farDock.tileY - 2, 0, far);
    expect((farBerth.y - behind.y) ** 2).toBeLessThanOrEqual(far.ship.dockRadius ** 2);
    expect(terrainAt(far.map, farDock.tileX, farDock.tileY - 1)).toBe(Terrain.Land);
    expect(sail(far, behind, INTERACT)).toEqual(behind);
    // Two rows south, the run is clear, and it moors from the longer reach.
    expect(sail(far, shipAt(farDock.tileX, farDock.tileY + 2, 0, far), INTERACT)).toMatchObject({ ...farBerth, dock: farDock.id });
  });

  it("moors a ship driven head-on at the land beside a corner dock, on the test island and at the real dock (23, 27)", () => {
    const southDock = config.map.docks.find((each) => each.tileX === 23 && each.tileY === 27)!;
    expect(southDock).toBeDefined();
    for (const [name, sea, target] of [["test island", cornerIsland, cornerIsland.map.docks[0]!], ["slice sea", config, southDock]] as const) {
      // Land directly west of the dock and open sea south of it: heading north (48), the lanes 336 and 368 sub-units
      // west of the berth run into that land's south face, about 395 sub-units from the berth, outside the reach.
      expect(terrainAt(sea.map, target.tileX - 1, target.tileY), name).toBe(Terrain.Land);
      expect(terrainAt(sea.map, target.tileX, target.tileY + 1), name).toBe(Terrain.Sea);
      const centre = tileCentre(sea, target.tileX, target.tileY);
      for (const offset of [-336, -368]) {
        for (const speed of [0, sea.ship.maxSpeed]) {
          const label = `${name}, offset ${offset}, speed ${speed}`;
          const start = { ...shipAt(target.tileX, target.tileY + 4, 48, sea), x: centre.x + offset, speed };
          expect(hullIsClear(sea, start.x, start.y), label).toBe(true);
          const course = sailFor(start, helm(0, 1, INTERACT_BUTTON), 60, sea);
          expect(course.at(-1), label).toMatchObject({ ...centre, speed: 0, dock: target.id, mooredThrottle: 1 });
        }
      }
    }
  });

  it("moors a ship that grounds in the real dock (23, 27)'s own row with its hull beside the berth", () => {
    // Heading north in column 25, two tiles east of the dock: the ship runs into the island's south face in the dock's
